-- TERMINALS
ON CONFLICT DO NOTHING;

-- USERS (drivers)
ON CONFLICT (email) DO NOTHING;

-- DRIVERS
SELECT id, 'DL-DRV-' || id, '2028-12-31', true, NOW() FROM "user" WHERE role = 'driver'
ON CONFLICT (user_id) DO NOTHING;

-- BUSES
ON CONFLICT (name) DO NOTHING;

ON CONFLICT (registration_number) DO NOTHING;

-- Non-AC state roadways fleet, available to the trip generator as regular buses.
ON CONFLICT (registration_number) DO NOTHING;

-- Add 30 dedicated Luxury and 30 dedicated Sleeper coaches for the Indian route network.
SELECT state_codes[((fleet.bus_no - 1) % cardinality(state_codes)) + 1] || '-01-BK-' ||
           (CASE WHEN bus_type.kind = 'Luxury' THEN 3000 ELSE 4000 END + fleet.bus_no)::text,
       CASE WHEN bus_type.kind = 'Luxury' THEN 'Luxury Premium 2+1 Intercity Coach' ELSE 'AC Sleeper Berth Coach 1+1' END,
       manufacturer_names[((fleet.bus_no - 1) % cardinality(manufacturer_names)) + 1],
       2023 + (fleet.bus_no % 4),
       36,
       CASE WHEN bus_type.kind = 'Luxury'
            THEN json_build_object('rows', 12, 'seatsPerRow', 3, 'layout', '2+1 premium', 'totalSeats', 36,
                                   'airConditioned', true, 'categories', json_build_object('PREMIUM', json_build_array('1','2','3')))
            ELSE json_build_object('rows', 18, 'seatsPerRow', 2, 'layout', '1+1 sleeper berths', 'totalSeats', 36,
                                   'airConditioned', true, 'categories', json_build_object('BERTH', json_build_array()))
       END,
       'ACTIVE', NOW(), NOW()
FROM generate_series(1, 30) AS fleet(bus_no)
CROSS JOIN (VALUES ('Luxury'), ('Sleeper')) AS bus_type(kind)
CROSS JOIN (SELECT ARRAY['AP','AR','AS','BR','CG','GA','GJ','HR','HP','JH','KA','KL','MP','MH','MN','ML','MZ','NL','OD','PB','RJ','SK','TN','TS','TR','UP','UK','WB'] AS state_codes,
                    ARRAY['Volvo','Scania','BharatBenz','Tata','Ashok Leyland','Eicher'] AS manufacturer_names) AS fleet_codes
ON CONFLICT (registration_number) DO NOTHING;

UPDATE bus
SET category_id = (
    SELECT id FROM bus_category WHERE name = CASE
        WHEN model ILIKE '%Sleeper%' THEN 'Sleeper'
        WHEN manufacturer ILIKE '%Roadways%' THEN 'Normal'
        WHEN registration_number ~ '-AB-10[0-9][0-9]$' AND right(registration_number, 4)::integer % 10 = 0 THEN 'Sleeper'
        WHEN registration_number ~ '-AB-10[0-9][0-9]$' AND right(registration_number, 4)::integer % 10 BETWEEN 1 AND 5 THEN 'Normal'
        WHEN manufacturer IN ('Volvo', 'Scania', 'Olectra', 'Switch Mobility', 'JBM') THEN 'Luxury'
        WHEN model ILIKE '%Luxury%' OR model ILIKE '%AC%' OR model ILIKE '%Premium%' THEN 'Luxury'
        ELSE 'Normal'
    END
)
WHERE category_id IS NULL;

-- Make the generated Normal seed fleet explicitly non-AC in its displayed model names.
UPDATE bus
SET model = regexp_replace(model, '( AC Intercity Coach| Luxury Seater)$', ' Non-AC Roadways Seater', 'i')
WHERE category_id = (SELECT id FROM bus_category WHERE name = 'Normal')
  AND registration_number ~ '-AB-10[0-9][0-9]$';

UPDATE bus
SET model = 'Sleeper ' || model
WHERE category_id = (SELECT id FROM bus_category WHERE name = 'Sleeper')
  AND registration_number ~ '-AB-10[0-9][0-9]$'
  AND model NOT ILIKE '%Sleeper%';

