        ('Jammu - Amritsar - Chandigarh - Shimla - Manali - Dehradun', ARRAY['Jammu', 'Amritsar', 'Chandigarh', 'Shimla', 'Manali', 'Dehradun']),
        ('Indore - Udaipur - Jaipur - Delhi - Chandigarh - Jammu', ARRAY['Indore', 'Udaipur', 'Jaipur', 'Delhi', 'Chandigarh', 'Jammu']),
        ('Srinagar - Jammu - Delhi - Agra - Gwalior - Bhopal - Nagpur', ARRAY['Srinagar', 'Jammu', 'Delhi', 'Agra', 'Gwalior', 'Bhopal', 'Nagpur']),
        ('Visakhapatnam - Vijayawada - Hyderabad - Bengaluru - Chennai', ARRAY['Visakhapatnam', 'Vijayawada', 'Hyderabad', 'Bengaluru', 'Chennai']),
        ('Kolkata - Ranchi - Varanasi - Lucknow - Agra - Jaipur', ARRAY['Kolkata', 'Ranchi', 'Varanasi', 'Lucknow', 'Agra', 'Jaipur']),
        ('Mumbai - Nashik - Indore - Bhopal - Jabalpur - Raipur - Bhubaneswar', ARRAY['Mumbai', 'Nashik', 'Indore', 'Bhopal', 'Jabalpur', 'Raipur', 'Bhubaneswar'])
), route_cities AS (
    SELECT d.route_name, c.city, c.stop_order::integer AS sequence_order
    FROM route_data d
    CROSS JOIN LATERAL unnest(d.cities) WITH ORDINALITY AS c(city, stop_order)
), located_stops AS (
    SELECT rc.route_name, rc.city, rc.sequence_order, t.id AS terminal_id,
           t.latitude, t.longitude,
           LAG(t.latitude) OVER (PARTITION BY rc.route_name ORDER BY rc.sequence_order) AS previous_latitude,
           LAG(t.longitude) OVER (PARTITION BY rc.route_name ORDER BY rc.sequence_order) AS previous_longitude,
           MAX(rc.sequence_order) OVER (PARTITION BY rc.route_name) AS final_sequence
    FROM route_cities rc
    JOIN terminal t ON t.city = rc.city AND t.country = 'India'
), segments AS (
    SELECT ls.*,
           CASE WHEN ls.previous_latitude IS NULL THEN 0::double precision ELSE
             2 * 6371 * 1.22 * ASIN(SQRT(LEAST(1::double precision, GREATEST(0::double precision,
               POWER(SIN(RADIANS((ls.latitude - ls.previous_latitude)::double precision / 2)), 2) +
               COS(RADIANS(ls.previous_latitude::double precision)) *
               COS(RADIANS(ls.latitude::double precision)) *
               POWER(SIN(RADIANS((ls.longitude - ls.previous_longitude)::double precision / 2)), 2)
             ))))
           END AS segment_km
    FROM located_stops ls
), cumulative_stops AS (
    SELECT s.*,
           SUM(s.segment_km) OVER (PARTITION BY s.route_name ORDER BY s.sequence_order) AS distance_km
    FROM segments s
)
                        departure_offset_minutes, distance_from_origin, base_price_from_origin)
SELECT r.id,
       cs.terminal_id,
       cs.sequence_order,
       ROUND(cs.distance_km / 52.0 * 60 + (cs.sequence_order - 1) * 15)::integer,
       CASE WHEN cs.sequence_order = cs.final_sequence
            THEN ROUND(cs.distance_km / 52.0 * 60 + (cs.sequence_order - 1) * 15)::integer
            ELSE ROUND(cs.distance_km / 52.0 * 60 + (cs.sequence_order - 1) * 15)::integer + 10
       END,
       ROUND(cs.distance_km::numeric, 1),
       ROUND((cs.distance_km * 1.70)::numeric, 2)
FROM cumulative_stops cs
JOIN route r ON r.name = cs.route_name
ON CONFLICT (route_id, sequence_order) DO NOTHING;

-- Make this category fleet eligible for every active Indian route.
SELECT b.id, r.id
FROM bus b CROSS JOIN route r
WHERE r.is_active = true
  AND (b.registration_number LIKE '%-BK-3%' OR b.registration_number LIKE '%-BK-4%')
ON CONFLICT (bus_id, route_id) DO NOTHING;
